/**
 * Converts a validated AI plan into a task description.
 * The estimate is labelled as AI-generated so nobody treats it as a guarantee.
 */
export function buildTaskDescription(plan) {
  return [
    `AI-generated plan · priority: ${plan.priority} · estimated effort: ~${plan.estimatedHours}h`,
    '',
    ...plan.steps.map((step, index) => `${index + 1}. ${step}`),
    '',
    'Note: this estimate was generated by an AI model and may be inaccurate.',
  ].join('\n');
}

/**
 * Human-readable hint for AI failures, based on the HTTP status returned by our API.
 */
export function getPlanErrorMessage(status, message) {
  if (status === 429) {
    return 'The AI provider is rate-limiting requests right now. Wait a few seconds and try again.';
  }
  if (status === 503) {
    return 'The AI planner is not configured on the server. Add GROQ_API_KEY to the server .env file and restart it.';
  }
  if (status === 504) {
    return 'The AI request timed out. Try a shorter description or retry in a moment.';
  }
  if (status === 400) {
    return message || 'Please check the description and try again.';
  }
  return message || 'The plan could not be generated. Please try again.';
}

/**
 * Clipboard-safe plain-text rendering used by "Copy plan".
 */
export function formatPlanAsText(plan) {
  return [
    plan.summary,
    `Priority: ${plan.priority}`,
    `Estimated effort: ~${plan.estimatedHours} hours`,
    '',
    ...plan.steps.map((step, index) => `${index + 1}. ${step}`),
    '',
    'Note: AI-generated estimates are suggestions and may not be exact.',
  ].join('\n');
}
